import sys


def main():
    tok = sys.stdin.read().split()
    n = int(tok[0])
    root = {}
    for w in tok[1:1 + n]:
        node = root
        for ch in w:
            node = node.setdefault(ch, {})
            node[0] = node.get(0, 0) + 1
    q = int(tok[1 + n])
    out = []
    for pre in tok[2 + n:2 + n + q]:
        node = root
        for ch in pre:
            node = node.get(ch)
            if node is None:
                break
        out.append(str(node[0]) if node is not None else '0')
    print('\n'.join(out))


main()

