#include <array>
#include <iostream>
#include <string>
#include <vector>
using namespace std;

struct Node {
    array<int, 26> next;
    int count = 0;
    Node() { next.fill(-1); }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n;
    vector<Node> trie(1);
    for (int i = 0; i < n; i++) {
        string w;
        cin >> w;
        int cur = 0;
        for (char ch : w) {
            int c = ch - 'a';
            if (trie[cur].next[c] < 0) {
                trie[cur].next[c] = (int)trie.size();
                trie.emplace_back();
            }
            cur = trie[cur].next[c];
            trie[cur].count++;
        }
    }
    cin >> q;
    while (q--) {
        string pre;
        cin >> pre;
        int cur = 0;
        for (char ch : pre) {
            cur = trie[cur].next[ch - 'a'];
            if (cur < 0) break;
        }
        cout << (cur < 0 ? 0 : trie[cur].count) << '\n';
    }
    return 0;
}

